cssRules:
.pill-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}
.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  font-size: 12px;
  border-radius: 9999px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #a1a1aa;
  cursor: pointer;
  transition: all 0.15s ease;
}
.pill:hover {
  background: rgba(255, 255, 255, 0.09);
  color: #f4f4f5;
  border-color: rgba(255, 255, 255, 0.2);
}
.pill.active {
  background: #3b82f6;
  border-color: #3b82f6;
  color: #ffffff;
  box-shadow: 0 0 12px rgba(59, 130, 246, 0.35);
}
.pill .count {
  font-size: 10px;
  opacity: 0.8;
}
